-- The bare-hand expected text and indices are independently transcribed from
-- the same-state GPGX frame, not generated by the port. ROM provenance is
-- recorded beside #43 in /workspace/shadowrun/out/progress_notes.md.
local E = require("enums")
local EquipmentStatus = require("menu.rules.command_equipment_status")
local Weapons = require("data.weapons").by_id

local function check(condition, label)
    if not condition then
        print("FAIL " .. label)
        return false
    end
    return true
end

local expected = {}
local fixture = assert(io.open(
    "decompilation/gameplay/tests_lua/fixtures/command_status_barehand_gpgx.tsv",
    "r"))
for line in fixture:lines() do
    if line:sub(1, 1) ~= "#" and line ~= "" then
        local key, value = line:match("^([^\t]+)\t(.*)$")
        assert(key and value, "malformed GPGX fixture row: " .. line)
        expected[key] = value:gsub("\\n", "\n")
    end
end
fixture:close()

local passed, total = 0, 0
local function expect(condition, label)
    total = total + 1
    if check(condition, label) then passed = passed + 1 end
end

local barehand = EquipmentStatus.command_view({
    equipped_action_code = E.ItemId.NONE,
    equipped_weapon_id = nil,
    equipped_armor_id = nil,
    cyberware_flags = 0,
    attributes = { strength = 2 },
})
expect(barehand.action_name == expected.action_name,
       "empty-hand label matches the GPGX frame's two padded source lines")
expect(barehand.damage_effect_label == expected.damage_label and
       barehand.damage_bar_index == tonumber(expected.damage_bar_index),
       "bare-hand Damage/Stun text and strip match the GPGX frame")
expect(barehand.power_label_index == tonumber(expected.power_label_index),
       "bare-hand Power label row matches the GPGX frame")
expect(barehand.no_armor and barehand.armor_item_id == "" and
       barehand.armor_label == expected.armor_label,
       "missing armor uses the ROM No Armor label observed in GPGX")

-- The ROM checks +0x90 bit 3 before bit 2 at 0x12EAE. These combinations
-- protect the source-driven override rows without copying screen captures.
local razors = EquipmentStatus.command_view({
    equipped_action_code = E.ItemId.NONE, cyberware_flags = E.CyberwareMask.HAND_RAZORS,
    attributes = { strength = 2 },
})
expect(razors.damage_bar_index == E.CommandStatusDamageBar.HAND_RAZORS and
       razors.damage_effect_label == "",
       "Hand Razors select their ROM damage strip without the Stun text")
local spurs_and_razors = EquipmentStatus.command_view({
    equipped_action_code = E.ItemId.NONE,
    cyberware_flags = E.CyberwareMask.HAND_RAZORS | E.CyberwareMask.SPURS,
    attributes = { strength = 2 },
})
expect(spurs_and_razors.damage_bar_index == E.CommandStatusDamageBar.STUN and
       spurs_and_razors.damage_effect_label == "",
       "Spurs win the ROM bit-3-before-bit-2 damage-strip selection")

local weapon_ids = { "streetline", "american_l36", "warhawk", "ak_97",
                     "mach_22", "frag", "scatter", "concussion" }
for _, weapon_id in ipairs(weapon_ids) do
    local weapon = Weapons[weapon_id]
    local weapon_view = EquipmentStatus.command_view({
        equipped_weapon_id = weapon_id,
        equipped_action_code = E.ItemId.AMERICAN_L36,
        equipped_armor_id = "armor_clothing",
        cyberware_flags = 0,
        attributes = { strength = 2 },
    })
    local bar = ({
        [E.WeaponDamageEffect.LIGHT] = E.WeaponDamageBar.LIGHT,
        [E.WeaponDamageEffect.MEDIUM] = E.WeaponDamageBar.MEDIUM,
        [E.WeaponDamageEffect.HEAVY] = E.WeaponDamageBar.HEAVY,
    })[weapon.damage_effect]
    expect(weapon_view.damage_bar_index == bar and
           weapon_view.power_label_index == math.max(0, math.min(12,
               weapon.power_rating - 1)) and
           not weapon_view.no_armor and
           weapon_view.armor_item_id == "armor_clothing",
           "weapon and armor summary derives from ROM-backed item data: " ..
               weapon_id)
end

print(string.format("command_equipment_status_tests: %d/%d passed",
                    passed, total))
if passed ~= total then os.exit(1) end
